8. Open vSwitch (OVS)
8.1. Setup OVS trên Fedora
# Cài đặt
sudo dnf5 install -y openvswitch
sudo systemctl enable --now openvswitch

# Tạo OVS bridge
sudo ovs-vsctl add-br ovs-br0

# Gán uplink
sudo ovs-vsctl add-port ovs-br0 enp1s0

# Set IP cho OVS bridge
sudo ip addr add 10.0.0.5/24 dev ovs-br0
sudo ip link set ovs-br0 up

# Verify
sudo ovs-vsctl show
8.2. libvirt với OVS
&lt;!-- Network definition --&gt;
&lt;network&gt;
  &lt;name&gt;ovs-network&lt;/name&gt;
  &lt;forward mode=&#039;bridge&#039;/&gt;
  &lt;bridge name=&#039;ovs-br0&#039;/&gt;
  &lt;virtualport type=&#039;openvswitch&#039;/&gt;
&lt;/network&gt;

&lt;!-- VM interface --&gt;
&lt;interface type=&#039;bridge&#039;&gt;
  &lt;source bridge=&#039;ovs-br0&#039;/&gt;
  &lt;virtualport type=&#039;openvswitch&#039;&gt;
    &lt;parameters profileid=&#039;myvm-port&#039;/&gt;
  &lt;/virtualport&gt;
  &lt;model type=&#039;virtio&#039;/&gt;
&lt;/interface&gt;
8.3. VLAN với OVS
# Access port (untag VLAN 100)
sudo ovs-vsctl set port vnet0 tag=100

# Trunk port
sudo ovs-vsctl set port vnet0 trunks=100,200,300

# Native VLAN + trunk
sudo ovs-vsctl set port vnet0 tag=100 trunks=100,200,300

9. Network Filters (nwfilter)
9.1. Khái niệm
nwfilter = firewall rules áp dụng per-vNIC, được libvirt quản lý:
# Liệt kê built-in filters
virsh nwfilter-list
# UUID                                  Name
# ...                                   clean-traffic
# ...                                   allow-dhcp
# ...                                   allow-arp
# ...                                   no-ip-spoofing
# ...                                   no-mac-spoofing
9.2. Áp dụng nwfilter cho VM
&lt;!-- Trong VM interface --&gt;
&lt;interface type=&#039;bridge&#039;&gt;
  &lt;source bridge=&#039;br0&#039;/&gt;
  &lt;model type=&#039;virtio&#039;/&gt;
  &lt;filterref filter=&#039;clean-traffic&#039;&gt;
    &lt;parameter name=&#039;IP&#039; value=&#039;10.0.0.100&#039;/&gt;
  &lt;/filterref&gt;
&lt;/interface&gt;
clean-traffic filter kết hợp:

no-mac-spoofing: chặn VM đổi MAC
no-ip-spoofing: chặn VM dùng IP khác
no-arp-spoofing: chặn ARP spoofing
allow-dhcp: cho phép DHCP


10. Troubleshooting Network
# Kiểm tra bridge
bridge link show
ip link show type bridge

# Kiểm tra VM network interfaces
virsh domiflist myvm
virsh domifaddr myvm --source agent  # cần guest agent

# Kiểm tra virbr0 (NAT network)
ip addr show virbr0
sudo iptables -t nat -L POSTROUTING -n -v | grep virbr0

# Kiểm tra dnsmasq (DHCP server)
ps aux | grep dnsmasq
cat /var/lib/libvirt/dnsmasq/default.status  # DHCP leases

# Packet capture trên bridge
sudo tcpdump -i virbr0 -n | head -20

# Kiểm tra OVS
sudo ovs-vsctl show
sudo ovs-ofctl dump-flows ovs-br0

# DHCP lease không nhận được?
# 1. Kiểm tra network đang active: virsh net-list
# 2. Kiểm tra dnsmasq running: ps aux | grep dnsmasq
# 3. Kiểm tra firewall: sudo firewall-cmd --list-all
# 4. Kiểm tra VM dùng đúng network: virsh domiflist myvm

